package observation

import (
	"fmt"
	"math"
	"os"
	"path/filepath"
	"regexp"
	"strings"

	"gopkg.in/yaml.v3"
)

// Rules is the distilled signature data the config-driven signatures consume,
// loaded once at boot from configs/signatures/*.yaml (generated by tools/sigimport
// from pinned OSS sources — gitleaks/ZAP/nuclei). Engine LOGIC stays in Go; only
// the DATA lives in config ("config is data, not code"). Loading is fail-closed:
// a bad/absent regex or file refuses startup rather than silently detecting less.
type Rules struct {
	Secrets      []SecretRule     // secrets.yaml — gitleaks
	LibraryPaths []*regexp.Regexp // secrets.yaml — skip secret-scanning these asset URLs (jquery/bootstrap/…)
	URLParams    []string         // url-sensitive.yaml — ZAP sensitive param names (lowercased)
	Internal     InternalRules    // internal-disclosure.yaml — ZAP Private-IP + heuristic
	APIDocs      APIDocRules      // api-docs.yaml — nuclei exposed-API surfaces
}

// SecretRule is one gitleaks-distilled secret pattern. MinEntropy 0 disables the
// entropy gate (token formats where the shape itself is the evidence).
type SecretRule struct {
	Name       string
	Re         *regexp.Regexp
	MinEntropy float64
	Keywords   []string
	Allow      []*regexp.Regexp
}

// InternalRules detect internal/infra disclosure (RFC1918 IPs, EC2 hostnames,
// non-prod host markers). RFC1918 carries a Go-side boundary guard (see the sig)
// because ZAP's original used PCRE lookaround, unavailable in RE2.
type InternalRules struct {
	RFC1918      *regexp.Regexp
	EC2Host      *regexp.Regexp
	NonProdHosts *regexp.Regexp
}

// APIDocRules detect an exposed API-documentation surface: a request path in Paths
// whose response body contains a BodyMarker (avoids path-only false positives).
type APIDocRules struct {
	Paths       []string
	BodyMarkers []*regexp.Regexp
}

// match returns the matched body-marker evidence when the path is an api-doc path
// AND the body confirms it, else "". Path matches exactly or as a suffix (so a
// mounted API under a prefix still hits).
func (a APIDocRules) match(path string, body []byte) (ev string, offset, matchLen int, ok bool) {
	hit := false
	for _, p := range a.Paths {
		if path == p || strings.HasSuffix(path, p) {
			hit = true
			break
		}
	}
	if !hit {
		return "", 0, 0, false
	}
	for _, m := range a.BodyMarkers {
		if loc := m.FindIndex(body); loc != nil {
			return snippet(body[loc[0]:loc[1]]), loc[0], loc[1] - loc[0], true
		}
	}
	return "", 0, 0, false
}

// ---- on-disk shapes (match tools/sigimport output) ----

type secretsFile struct {
	LibraryPaths []string `yaml:"libraryPaths"`
	Rules        []struct {
		Name       string   `yaml:"name"`
		Regex      string   `yaml:"regex"`
		MinEntropy float64  `yaml:"minEntropy"`
		Keywords   []string `yaml:"keywords"`
		Allow      []string `yaml:"allow"`
	} `yaml:"rules"`
}
type urlSensitiveFile struct {
	Params []string `yaml:"params"`
}
type internalFile struct {
	RFC1918      string `yaml:"rfc1918"`
	EC2Host      string `yaml:"ec2Host"`
	NonProdHosts string `yaml:"nonProdHosts"`
}
type apiDocsFile struct {
	Paths       []string `yaml:"paths"`
	BodyMarkers []string `yaml:"bodyMarkers"`
}

// LoadRules reads configs/signatures/ (fail-closed): every listed regex must
// compile under RE2, and every expected file must be present, or startup aborts —
// a scanner that silently loaded no secret rules would report false-clean.
func LoadRules(dir string) (Rules, error) {
	var r Rules

	var sf secretsFile
	if err := readYAML(filepath.Join(dir, "secrets.yaml"), &sf); err != nil {
		return r, err
	}
	for _, p := range sf.LibraryPaths {
		re, err := regexp.Compile(p)
		if err != nil {
			return r, fmt.Errorf("secrets.yaml libraryPath %q: %w", p, err)
		}
		r.LibraryPaths = append(r.LibraryPaths, re)
	}
	for _, rule := range sf.Rules {
		re, err := regexp.Compile(rule.Regex)
		if err != nil {
			return r, fmt.Errorf("secrets.yaml rule %q: %w", rule.Name, err)
		}
		sr := SecretRule{Name: rule.Name, Re: re, MinEntropy: rule.MinEntropy, Keywords: rule.Keywords}
		for _, a := range rule.Allow {
			are, err := regexp.Compile(a)
			if err != nil {
				return r, fmt.Errorf("secrets.yaml rule %q allow %q: %w", rule.Name, a, err)
			}
			sr.Allow = append(sr.Allow, are)
		}
		r.Secrets = append(r.Secrets, sr)
	}

	var uf urlSensitiveFile
	if err := readYAML(filepath.Join(dir, "url-sensitive.yaml"), &uf); err != nil {
		return r, err
	}
	r.URLParams = uf.Params

	var inf internalFile
	if err := readYAML(filepath.Join(dir, "internal-disclosure.yaml"), &inf); err != nil {
		return r, err
	}
	for name, pat := range map[string]*string{"rfc1918": &inf.RFC1918, "ec2Host": &inf.EC2Host, "nonProdHosts": &inf.NonProdHosts} {
		if *pat == "" {
			return r, fmt.Errorf("internal-disclosure.yaml: missing %s", name)
		}
	}
	var err error
	if r.Internal.RFC1918, err = regexp.Compile(inf.RFC1918); err != nil {
		return r, fmt.Errorf("internal-disclosure rfc1918: %w", err)
	}
	if r.Internal.EC2Host, err = regexp.Compile(inf.EC2Host); err != nil {
		return r, fmt.Errorf("internal-disclosure ec2Host: %w", err)
	}
	if r.Internal.NonProdHosts, err = regexp.Compile(inf.NonProdHosts); err != nil {
		return r, fmt.Errorf("internal-disclosure nonProdHosts: %w", err)
	}

	var af apiDocsFile
	if err := readYAML(filepath.Join(dir, "api-docs.yaml"), &af); err != nil {
		return r, err
	}
	r.APIDocs.Paths = af.Paths
	for _, m := range af.BodyMarkers {
		re, err := regexp.Compile(`(?i)` + regexp.QuoteMeta(m))
		if err != nil {
			return r, fmt.Errorf("api-docs marker %q: %w", m, err)
		}
		r.APIDocs.BodyMarkers = append(r.APIDocs.BodyMarkers, re)
	}
	return r, nil
}

func readYAML(path string, v any) error {
	// #nosec G304 -- path is an operator-supplied config location, same trust
	// boundary as the mapping/coverage loaders.
	b, err := os.ReadFile(path)
	if err != nil {
		return fmt.Errorf("signature config: %w", err)
	}
	if err := yaml.Unmarshal(b, v); err != nil {
		return fmt.Errorf("signature config %s: %w", filepath.Base(path), err)
	}
	return nil
}

// shannon returns the Shannon entropy (bits/char) of s — the gitleaks-style gate
// that separates a real high-entropy secret value from low-entropy noise like a
// minified-JS `!0` or an ordinary English word.
func shannon(s string) float64 {
	if s == "" {
		return 0
	}
	var freq [256]float64
	for i := 0; i < len(s); i++ {
		freq[s[i]]++
	}
	n := float64(len(s))
	var h float64
	for _, c := range freq {
		if c == 0 {
			continue
		}
		p := c / n
		h -= p * math.Log2(p)
	}
	return h
}
